Here's how to implement a debounced search bar in React using a custom hook:

```jsx
import { useState, useEffect } from 'react';

function useDebounce(value, delay) {
    const [debouncedValue, setDebouncedValue] = useState(value);

    useEffect(() => {
        const timer = setTimeout(() => {
            setDebouncedValue(value);
        }, delay);

        return () => clearTimeout(timer);
    }, [value, delay]);

    return debouncedValue;
}

function SearchBar() {
    const [searchTerm, setSearchTerm] = useState('');
    const debouncedSearch = useDebounce(searchTerm, 300);

    // API call when debounced value changes
    useEffect(() => {
        if (debouncedSearch) {
            fetchSearchResults(debouncedSearch);
        }
    }, [debouncedSearch]);

    async function fetchSearchResults(query) {
        try {
            const response = await fetch(`/api/search?q=${encodeURIComponent(query)}`);
            const data = await response.json();
            console.log('Results:', data);
        } catch (error) {
            console.error('Search failed:', error);
        }
    }

    return (
        <div>
            <input
                type="text"
                placeholder="Search..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
            />
            <p>Searching for: {debouncedSearch}</p>
        </div>
    );
}
```

The hook delays updating the value by the specified delay (300ms is standard for search). This prevents the API call on every keystroke. Only after the user stops typing for 300ms does the search fire.
